// Shared helpers for the animated-GIF promotion specs.
//
// TWO_FRAME_GIF is a 16×9 GIF89a with two 400ms frames (red/blue checkerboard,
// inverted on frame 2) and a NETSCAPE loop block. It is generated by hand, not
// by an image library, so the test has no build-time dependency. Anything that
// flattens it to one frame (the canvas cropper, next/image's optimizer) makes
// countGifFrames() return 1.

import { v2 as cloudinary } from 'cloudinary';

const TWO_FRAME_GIF_BASE64 =
  '';

export const TWO_FRAME_GIF = Buffer.from(TWO_FRAME_GIF_BASE64, 'base64');

/**
 * Count the image frames in a GIF by walking its blocks. Returns 0 for a
 * non-GIF and throws on malformed block data.
 */
export function countGifFrames(data: Buffer): number {
  const header = data.subarray(0, 6).toString('ascii');
  if (header !== 'GIF87a' && header !== 'GIF89a') return 0;

  const flags = data[10];
  let pos = 13 + (flags & 0x80 ? 3 * 2 ** ((flags & 7) + 1) : 0);
  let frames = 0;

  const skipSubBlocks = () => {
    while (data[pos] !== 0) pos += data[pos] + 1;
    pos += 1;
  };

  while (pos < data.length) {
    const block = data[pos++];
    if (block === 0x3b) return frames;
    if (block === 0x21) {
      pos += 1; // extension label
      skipSubBlocks();
    } else if (block === 0x2c) {
      frames += 1;
      const imageFlags = data[pos + 8];
      pos += 9;
      if (imageFlags & 0x80) pos += 3 * 2 ** ((imageFlags & 7) + 1);
      pos += 1; // LZW minimum code size
      skipSubBlocks();
    } else {
      throw new Error(`countGifFrames: unexpected block 0x${block.toString(16)} at ${pos - 1}`);
    }
  }
  throw new Error('countGifFrames: missing GIF trailer');
}

/** Delete an uploaded Cloudinary image created by a test run. */
export async function destroyCloudinaryImage(publicId: string): Promise<void> {
  cloudinary.config({
    cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
    api_key: process.env.CLOUDINARY_API_KEY,
    api_secret: process.env.CLOUDINARY_API_SECRET,
    secure: true,
  });
  await cloudinary.uploader.destroy(publicId, { resource_type: 'image' }).catch(() => undefined);
}
